class Solution {
public:
    int islandPerimeter(vector<vector<int>>& grid) {
        int fence = 0;
        for (int r = 0; r < (int)grid.size(); r++) {
            for (int c = 0; c < (int)grid[0].size(); c++) {
                if (!grid[r][c]) continue;
                fence += 4;
                if (r > 0 && grid[r - 1][c]) fence -= 2;
                if (c > 0 && grid[r][c - 1]) fence -= 2;
            }
        }
        return fence;
    }
};
